import assert from 'node:assert/strict'
import { join } from 'node:path'
import { DatabaseSync } from 'node:sqlite'
import { setImmediate } from 'node:timers/promises'
import { test } from 'node:test'
import { fixture, main, outsider, ownerSource, relaySource, reviewer, until, worker } from './host-fixture.mjs'

const exactTitle = '00-main'
const question = '做了那些事情'
const exactInput = '你问一下' + exactTitle + question
const modelText = '[model changed: assistant turns above this point were generated by deepseek-v4-flash; the session continues with deepseek-v4-pro]'
const modelSelection = { kind: 'model-selection', form: 'notice', summary: 'deepseek-v4-flash → deepseek-v4-pro' }

async function completedQuestion(host, owner, target, goal) {
  const notice = await host.receive(target)
  assert.equal(notice.source.bridgeWorkflowKind, 'task')
  assert.equal(notice.source.senderSessionId, owner)
  const id = notice.source.bridgeWorkflowId
  const claim = await host.call(target, 'workflow_claim', { id })
  assert.equal(claim.owner, owner)
  assert.equal(claim.goal, goal)
  assert.equal(claim.instructions, goal)
  const summary = '合成原窗回报。'
  const report = await host.call(target, 'workflow_report', {
    id, attempt: claim.attempt, token: claim.token, status: 'completed', summary, evidence: ['synthetic-autonomy'],
  })
  assert.equal(report.duplicate, false)
  host.end(target)
  const result = await host.receive(owner)
  assert.equal(result.source.bridgeWorkflowKind, 'result')
  assert.equal(result.source.bridgeWorkflowId, id)
  assert.equal(result.source.bridgeWorkflowOwner, owner)
  assert(result.content[0].text.includes(summary))
  host.end(owner)
  await until(async () => {
    host.begin(owner, '核对合成原窗的任务。')
    const state = await host.call(owner, 'workflow_status', { task: claim.task })
    host.end(owner)
    return state.state === 'closed'
  }, 'Expected the task to close after the native result')
  assert.deepEqual(host.deliveries.map(({ target }) => target), [target, owner])
}

test('an exact named question is sent once despite both ordinary tools being selected', async t => {
  const host = await fixture(t)
  host.rename(main, exactTitle)
  host.begin(worker, exactInput)
  for (const result of [
    await host.call(worker, 'send_session_message', { to: main, request_id: 'synthetic-legacy', text: question }),
    await host.call(worker, 'send_natural_session_message', {}),
  ]) {
    assert.equal(result?.error, undefined, JSON.stringify(result))
  }
  assert.deepEqual(host.deliveries, [])
  host.end(worker)
  await completedQuestion(host, worker, main, question)
})

test('the original owner text remains authoritative over arguments to a mistaken ordinary tool', async t => {
  const host = await fixture(t)
  host.rename(main, exactTitle)
  host.begin(worker, exactInput)
  await host.call(worker, 'send_session_message', {
    to: outsider, request_id: 'synthetic-mismatched-legacy', text: '不得成为委托任务的合成正文',
  })
  assert.deepEqual(host.deliveries, [])
  host.end(worker)
  await completedQuestion(host, worker, main, question)
})

test('a native model-selection notice keeps the exact owner turn eligible for one direct question', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成查询')
  host.begin(main, '你给合成查询这个窗口问他今天气温怎么样')
  host.appendInput(main, modelText, modelSelection)
  host.end(main)
  await completedQuestion(host, main, worker, '今天气温怎么样')
})

for (const [name, source] of [['owner', ownerSource], ['relay', relaySource]]) {
  test('model-switch text from an additional ' + name + ' input cannot preserve the owner-turn authority', async t => {
    const host = await fixture(t)
    host.rename(worker, '合成查询')
    host.begin(main, '你给合成查询这个窗口问他今天气温怎么样')
    host.appendInput(main, modelText, source)
    host.end(main)
    await setImmediate()
    assert.deepEqual(host.deliveries, [])
  })
}

for (const name of ['archived', 'unknown']) {
  test('an ' + name + ' longer title cannot authorize a shorter-prefix assignment', async t => {
    const host = await fixture(t)
    host.rename(worker, '合成审核')
    if (name === 'archived') {
      host.rename(outsider, '合成审核备用')
      host.archive(outsider)
    }
    const ledger = new DatabaseSync(join(process.env.DSH_HOME, 'profile', 'dsh-session-bridge-workflow', 'workflow-v1.sqlite'))
    t.after(() => ledger.close())

    host.begin(main, '你问一下合成审核备用窗口多大内存够用')
    host.end(main)
    await setImmediate()
    const state = JSON.parse(ledger.prepare('SELECT body FROM ledger').get().body)
    assert.deepEqual(state.grants, {})
    assert.deepEqual(state.jobs, {})
    assert.equal(host.deliveries.filter(({ message }) => message.source.bridgeWorkflowKind === 'task').length, 0)
  })
}

test('an explicitly named ordinary message cannot enter another active task through the old sender', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成乙审')
  for (const [target, title] of [[worker, '合成甲审'], [reviewer, '合成乙审']]) {
    host.begin(main, '让「' + title + '」窗口核对合成项目')
    host.end(main)
    const assignment = await host.receive(target)
    assert.equal(assignment.source.bridgeWorkflowKind, 'task')
    assert.equal((await host.call(target, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })).duplicate, false)
    host.end(target)
  }

  const text = '只读核对甲项的合成补充。'
  host.begin(main, '请给合成甲审窗口发消息：' + text)
  const receipt = await host.call(main, 'send_session_message', {
    to: reviewer, request_id: 'synthetic-wrong-ordinary-target', text,
  })
  host.end(main)
  if (receipt?.to === reviewer && receipt.delivery === 'queued') {
    const settled = await until(async () => {
      const value = await host.call(main, 'session_message_status', { request_id: receipt.requestId, job: receipt.job })
      return value.delivery !== 'unknown' && value
    }, 'Expected the ordinary message attempt to settle')
    assert.equal(settled.delivery, 'not_delivered')
  }
  assert(!host.deliveries.some(({ target, message }) => target === reviewer &&
    message.content.some(({ text: body }) => body?.endsWith(text))))
})

test('the natural sender keeps a named follow-up and its plain reply in the selected active task', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成乙审')
  const claims = new Map()
  for (const [target, title] of [[worker, '合成甲审'], [reviewer, '合成乙审']]) {
    host.begin(main, '让「' + title + '」窗口核对合成项目')
    host.end(main)
    const assignment = await host.receive(target)
    assert.equal(assignment.source.bridgeWorkflowKind, 'task')
    const claim = await host.call(target, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })
    assert.equal(claim.duplicate, false)
    claims.set(target, claim)
    host.end(target)
  }

  const text = '请核对甲审任务中的第二份合成样本。'
  host.begin(main, '给合成甲审窗口发消息：' + text)
  const receipt = await host.call(main, 'send_natural_session_message', {})
  assert.equal(receipt.delivery, 'queued')
  assert.equal(receipt.job, claims.get(worker).id)
  host.end(main)

  const followUp = await host.receive(worker)
  assert.equal(followUp.source.bridgeWorkflowKind, 'conversation')
  assert.equal(followUp.source.bridgeWorkflowId, claims.get(worker).id)
  assert(followUp.content[0].text.endsWith(text))
  const answer = '第二份合成样本已核对。'
  host.reply(worker, answer)
  host.end(worker)

  const response = await host.receive(main)
  assert.equal(response.source.bridgeWorkflowKind, 'conversation')
  assert.equal(response.source.bridgeWorkflowId, claims.get(worker).id)
  assert(response.content[0].text.endsWith(answer))
  host.end(main)
  assert.deepEqual(host.deliveries.map(({ target }) => target), [worker, reviewer, worker, main])
})

test('an explicit natural message to a peer with no active task keeps ordinary delivery', async t => {
  const host = await fixture(t)
  host.rename(worker, '合成甲审')
  host.rename(reviewer, '合成资料')
  host.begin(main, '让「合成甲审」窗口核对合成项目')
  host.end(main)
  const assignment = await host.receive(worker)
  assert.equal(assignment.source.bridgeWorkflowKind, 'task')
  assert.equal((await host.call(worker, 'workflow_claim', { id: assignment.source.bridgeWorkflowId })).duplicate, false)
  host.end(worker)

  const text = '这是发往没有委托的窗口的合成消息。'
  host.begin(main, '给合成资料窗口发消息：' + text)
  const receipt = await host.call(main, 'send_natural_session_message', {})
  assert.equal(receipt.delivery, 'delivered')
  host.end(main)
  const message = await host.receive(reviewer)
  assert.equal(message.id, receipt.messageId)
  assert.equal(message.source.bridgeWorkflowKind, undefined)
  assert(message.content[0].text.endsWith(text))
  host.end(reviewer)
  assert.deepEqual(host.deliveries.map(({ target }) => target), [worker, reviewer])
})
